namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Invalid Student ID format.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public int? CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(string id);
    IReadOnlyList<Course> GetCourses(string? departmentId = null, string? searchTerm = null);
    IReadOnlyList<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics courses." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events and civilizations." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Topics include variables, control flow, methods, and object-oriented design.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "PhD in Computer Science from MIT. 15 years teaching introductory programming.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. Alan Turing", InstructorBio = "Researcher in computational complexity. Published 40+ papers on algorithm optimization.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Edgar Codd", InstructorBio = "Database systems expert with industry experience at major tech companies.", DepartmentId = "cs" },
        new() { Id = 4, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Euler Bernoulli", InstructorBio = "Specialist in applied mathematics with focus on mathematical modeling.", DepartmentId = "math", IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications to data science.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emmy Noether", InstructorBio = "Award-winning mathematician specializing in abstract algebra and theoretical physics.", DepartmentId = "math" },
        new() { Id = 6, CourseCode = "ENG 101", Title = "Composition & Rhetoric", Description = "Develop effective writing skills through essay composition, argumentation, and rhetorical analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Prof. Maya Angelou", InstructorBio = "Published author and writing instructor with 20 years of teaching experience.", DepartmentId = "eng" },
        new() { Id = 7, CourseCode = "ENG 220", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present day.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Prof. Toni Morrison", InstructorBio = "Literary scholar specializing in 20th-century American fiction.", DepartmentId = "eng", IsFeatured = true },
        new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to physics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Richard Feynman", InstructorBio = "Experimental physicist passionate about making physics accessible to all students.", DepartmentId = "phys" },
        new() { Id = 9, CourseCode = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM + Lab Fri 1:00–3:00 PM", InstructorName = "Dr. James Maxwell", InstructorBio = "Theoretical physicist with research focus on quantum electrodynamics.", DepartmentId = "phys" },
        new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of global civilizations from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Howard Zinn", InstructorBio = "Historian specializing in social movements and cross-cultural interactions.", DepartmentId = "hist" },
        new() { Id = 11, CourseCode = "HIST 250", Title = "Modern European History", Description = "Europe from the Renaissance through the 21st century: politics, culture, and society.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Eric Hobsbawm", InstructorBio = "European history specialist with expertise in the Age of Revolution.", DepartmentId = "hist", IsFeatured = true },
        new() { Id = 12, CourseCode = "CS 450", Title = "Machine Learning", Description = "Supervised and unsupervised learning, neural networks, model evaluation, and practical applications.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. Ada Lovelace", InstructorBio = "PhD in Computer Science from MIT. 15 years teaching introductory programming.", DepartmentId = "cs" },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(string id) =>
        Departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? departmentId = null, string? searchTerm = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId == departmentId);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        Courses.FirstOrDefault(c => c.Id == id);
}

